const path = require("path");
const { pathToFileURL } = require("url");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const zc = require("zod");
  const esmPath = path.join(path.dirname(require.resolve("zod")), "index.js");
  const ze = await import(pathToFileURL(esmPath).href);
  if (typeof zc.config !== "function" || typeof ze.config !== "function") broken("z.config not found");
  if (zc.string === ze.string) broken("CJS and ESM builds are the same instance");
  zc.config({ customError: () => "custom-from-cjs" });
  const r = ze.string().safeParse(123);
  if (r.success) broken("ESM z.string() accepted a number");
  const msg = r.error.issues[0].message;
  if (msg !== "custom-from-cjs") symptom("z.config on the CJS instance did not reach the ESM instance");
  console.log("OK: z.config on the CJS instance applies to the ESM instance");
})().catch(e => broken(String(e && e.stack || e)));

